function setView(v){view=v;document.querySelectorAll(".scene>section").forEach(e=>e.classList.toggle("active",e.id===v));document.querySelectorAll("[data-view]").forEach(e=>e.classList.toggle("active",e.dataset.view===v));$("viewtitle").textContent={board:"插孔板：看插脚落在哪两个孔组",scope:"示波器：按键 → 菜单 → 看波形",generator:"信号源：选参数 → 输入数字 → 选单位",meter:"万用表：先选档，再接红黑夹",power:"直流电源：先设电压，再开输出"}[v];refresh()}
function setBaseline(){S=initial();S.parts=14;S.power=true;S.gen=true;S.ch1=S.ch2=S.ac1=S.ac2=S.trig=true;S.measures=[{source:1,type:"RMS"},{source:2,type:"RMS"},{source:1,type:"Frequency"}]}
function applyBefore(){if(ti===-1){S=initial();S.parts=Math.max(0,lessons[0].steps[si][6]-1);return}
setBaseline();if(ti===0){S.power=si>=3;S.gen=si>=7;S.ch1=S.ch2=S.ac1=S.ac2=si>=5;S.trig=si>=6;S.measures=[]}
if(ti===1&&si===2){S.ce=false;S.power=S.gen=false;}
if(ti===2){S.load=si===0?1000000:si===1?Infinity:10000}
if(ti===3){S.v1=.02;S.v2=2;S.pos1=S.pos2=4;if(si>=2){S.vc=5;S.ve=2.6}if(si===3){S.cut=true;S.power=S.gen=false}}
}
function renderLesson(){const L=lessons[ti+1],step=L.steps[si];$("tabs").innerHTML="";lessons.forEach((l,i)=>{const b=document.createElement("button");b.textContent=l.name;b.className=i===ti+1?"active":"";b.onclick=()=>{clearDemo();ti=i-1;si=0;applyBefore();renderLesson()};$("tabs").appendChild(b)});$("stepcount").textContent=L.name+" · "+(si+1)+"/"+L.steps.length;$("steptitle").textContent=step[0];$("steptext").textContent=step[1];$("stepaction").textContent=step[2];$("stepwhy").textContent=step[3];$("toast").textContent="";$("prev").disabled=si===0;$("next").textContent=si===L.steps.length-1?"进入下一项 →":"下一步 →";$("demo").disabled=false;$("steps").innerHTML="";L.steps.forEach((q,i)=>{const b=document.createElement("button");b.textContent=(i+1)+". "+q[0];b.className=i===si?"active":"";b.onclick=()=>{clearDemo();si=i;applyBefore();renderLesson()};$("steps").appendChild(b)});$("datasection").hidden=ti===-1;if(ti>=0)renderData();setView(step[4]);saveProgress()}
function clearDemo(){if(timer)clearTimeout(timer);timer=null;document.querySelectorAll(".flash").forEach(e=>e.classList.remove("flash"));$("demo").disabled=false}
function flash(id,msg){refresh();document.querySelectorAll(".flash").forEach(e=>e.classList.remove("flash"));if($(id))$(id).classList.add("flash");$("toast").textContent=msg;}
function sequence(list){clearDemo();$("demo").disabled=true;let i=0;function tick(){const item=list[i++];if(item){item[1]();flash(item[0],item[2]);timer=setTimeout(tick,1000)}else{clearDemo();$("toast").textContent="演示完成。也可以直接点击面板练习。";refresh()}}tick()}
function demo(){const q=lessons[ti+1].steps[si],a=q[5];
if(a==="node"){selectNode("B");$("toast").textContent="B 组的 9 孔一起亮：它们是同一个点。";return}
if(a==="install"){S.parts=q[6];drawBoard();$("toast").textContent="已插入本步元件/导线。点击孔组核对两端。";return}
const show=(v)=>()=>setView(v);
if(a==="gfrequency")sequence([["b-sine",()=>{S.sine=true}, "按 Sine：选正弦"],["b-freq",()=>{param="freq";entry="1"},"输入 1"],["b-freq",()=>{S.freq=1000;entry=""},"选择 kHz：1 kHz"]]);
if(a==="gamplitude")sequence([["b-amp",()=>{param="amp";entry="10"},"Amplitude 输入 10"],["b-amp",()=>{S.amp=10;entry=""},"选择 mV RMS"],["b-offset",()=>{S.offset=0},"Offset = 0 V"],["b-loadz",()=>{S.loadZ=true},"Load = High Z"]]);
if(a==="poweron")sequence([["b-poutput",()=>{S.voltage=12},"设定 12 V"],["b-poutput",()=>{S.power=true},"打开 CH1 输出"]]);
if(a==="qpoint")sequence([["b-dcv",()=>{meterMode="DCV";$("redpoint").value="C";$("blackpoint").value="E"},"DCV：红接 C、黑接 E"],["b-dcv",()=>{S.vc=7;S.ve=1},"调 R_P：U_CE ≈ 6 V"]]);
if(a==="coupling")sequence([["b-ch1",()=>{selected=1;S.ch1=true;menu="channel"},"按 1：设置 CH1"],["soft-0",()=>{S.ac1=true},"Coupling → AC"],["b-ch2",()=>{selected=2;S.ch2=true},"按 2：设置 CH2"],["soft-0",()=>{S.ac2=true},"Coupling → AC"]]);
if(a==="scales")sequence([["b-vscale",()=>{S.v1=.005;S.v2=1;S.physical=S.probe1=S.probe2=1},"CH1 5 mV/div；CH2 1 V/div"],["b-tscale",()=>{S.time=.0002},"Time 200 μs/div"],["b-trigger",()=>{menu="trigger";S.trig=true;S.level=0},"Edge / CH1 / ↑ / 0 V"]]);
if(a==="signalon")sequence([["b-goutput",()=>{setView("generator");S.gen=true},"CH1 Output → ON"],["b-run",show("scope"),"回示波器：输入/输出反相"]]);
if(a==="measure")sequence([["b-measure",()=>{menu="measure";S.measures=[];measureSource=1;measureType="RMS"},"Measure → Add Measurement"],["soft-3",()=>{addMeasure(1,"RMS")},"添加 CH1 RMS"],["soft-3",()=>{addMeasure(2,"RMS")},"添加 CH2 RMS"],["soft-3",()=>{addMeasure(1,"Frequency")},"添加 CH1 Frequency"]]);
if(a==="ceoff")sequence([["",()=>{S.power=S.gen=false},"关闭直流电源与信号源"],["",()=>{S.ce=false},"取下 C_E 插件块；保持偏置不变"]]);
if(a==="afterce")sequence([["",()=>{S.power=S.gen=true},"恢复供电与输入"],["b-vscale",()=>{S.v2=.05;menu="measure"},"输出较小：调 CH2 Scale 看清"]]);
if(a==="loadopen"||a==="load10k"||a==="load1k")sequence([["",()=>{S.power=S.gen=false;setView("board")},"先关闭双输出"],["",()=>{S.ce=true;S.load=a==="loadopen"?Infinity:a==="load10k"?10000:1000;drawBoard()},"更换负载；R_P 不变"],["",()=>{S.power=S.gen=true;setView("scope")},"恢复输出，读取 RMS"]]);
if(a==="normalmax")sequence([["",()=>{S.amp=10},"从 10 mV RMS 开始"],["b-amp",()=>{S.amp=16},"逐渐增大输入"],["b-amp",()=>{S.amp=24},"继续增大：开始削顶"],["b-amp",()=>{S.amp=17},"略减小，寻找最大无失真幅值"]]);
if(a==="saturation")sequence([["",()=>{S.gen=false},"关信号源，测静态点"],["",()=>{S.vc=5;S.ve=2.6;S.amp=10},"减小 R_P：V_C ≈ 5 V"],["",()=>{S.gen=true},"恢复输入：输出下部削平"]]);
if(a==="cutparts")sequence([["",()=>{S.power=S.gen=false},"关闭双输出"],["",()=>{S.cut=true;drawBoard()},"R_b1=100 kΩ；R_P=220 kΩ"]]);
if(a==="cutoff")sequence([["",()=>{S.power=true;S.cut=true;S.vc=11;S.ve=.1;S.amp=20},"调大 R_P：V_C≈11 V"],["",()=>{S.gen=true},"输入 20 mV RMS：输出上部削平"]]);
}
let meterMode="DCV";
function addMeasure(source,type){if(!S.measures.some(m=>m.source===source&&m.type===type))S.measures.push({source,type});S.measures=S.measures.slice(-4)}
function ui(){return S.gen&&S.sine?S.amp/1000*(S.loadZ?1:2):0}
function amplGain(){let g=S.ce?200:10;return g*(S.load===Infinity?1:(1/(1/2400+1/S.load))/2400)}
function out(t){if(!S.power||!S.gen||S.parts<11)return 0;const raw=-Math.SQRT2*ui()*amplGain()*Math.sin(2*Math.PI*S.freq*t);return Math.max(-(S.vc-S.ve-.2),Math.min(S.voltage-S.vc,raw))}
function outputRms(){let total=0;for(let i=0;i<1000;i++)total+=out(i/1000/S.freq)**2;return Math.sqrt(total/1000)}
function reading(source,type){const ratio=(source===1?S.probe1:S.probe2)/S.physical;if(type==="Frequency")return S.gen?(S.freq/1000).toFixed(3)+" kHz":"—";let val=source===1?ui():outputRms();return val*ratio<.1?(val*ratio*1000).toFixed(2)+" mV":(val*ratio).toFixed(3)+" V"}
function softMenu(){let buttons=[];if(menu==="channel")buttons=[["Coupling\n"+((selected===1?S.ac1:S.ac2)?"AC":"DC"),()=>{if(selected===1)S.ac1=!S.ac1;else S.ac2=!S.ac2}],["Invert\n"+((selected===1?S.inv1:S.inv2)?"ON":"OFF"),()=>{const k=selected===1?"inv1":"inv2";S[k]=!S[k];}],["Bandwidth\n"+((selected===1?S.bw1:S.bw2)?"20 MHz":"Full"),()=>{const k=selected===1?"bw1":"bw2";S[k]=!S[k];}],["Probe Setup\n"+(selected===1?S.probe1:S.probe2)+"X",()=>{let k=selected===1?"probe1":"probe2";S[k]=S[k]===1?10:1}],["CH"+selected+"\n当前通道",()=>{}]];
if(menu==="trigger")buttons=[["Type\nEdge",()=>{S.trig=true}],["Source\nCH1",()=>{S.trig=true}],["Slope\n↑",()=>{S.trig=true}],["Level\n0 V",()=>{S.level=0;S.trig=true}],["Mode\nAuto",()=>{}]];
if(menu==="measure")buttons=[["Add\nMeasurement",()=>{menu="measure"}],["Source\nCH"+measureSource,()=>{measureSource=measureSource===1?2:1}],["Type\n"+measureType,()=>{measureType=measureType==="RMS"?"Frequency":"RMS"}],["确认添加",()=>addMeasure(measureSource,measureType)],["清除测量",()=>{S.measures=[]}]];
$("soft").innerHTML="";buttons.forEach((x,i)=>{let b=document.createElement("button");b.id="soft-"+i;b.textContent=x[0];b.onclick=()=>{x[1]();refresh()};$("soft").appendChild(b)})}
function drawScope(){if(!S.run)return;const c=$("wave");let ctx;try{ctx=c.getContext("2d")}catch(e){return}if(!ctx)return;ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle="#0e1921";ctx.fillRect(0,0,720,340);ctx.strokeStyle="#3c515933";ctx.lineWidth=1;for(let x=0;x<=720;x+=72){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,340);ctx.stroke()}for(let y=0;y<=340;y+=42.5){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(720,y);ctx.stroke()}
const peak=Math.SQRT2*ui(),locked=S.trig&&peak>0&&Math.abs(S.level)<peak;const phase=(locked?Math.asin(S.level/peak)/(2*Math.PI*S.freq):(Date.now()%2000)/2000/S.freq)+S.hpos/S.freq;[1,2].forEach(ch=>{if(!(ch===1?S.ch1:S.ch2))return;let vdiv=ch===1?S.v1:S.v2,pos=(ch===1?S.pos1:S.pos2)*42.5,ratio=(ch===1?S.probe1:S.probe2)/S.physical;ctx.strokeStyle=ch===1?"#f8d44d":"#47dbe2";ctx.lineWidth=2;ctx.beginPath();for(let x=0;x<720;x++){let t=x/720*S.time*10+phase,amp=ch===1?Math.SQRT2*ui()*Math.sin(2*Math.PI*S.freq*t):out(t);if(!(ch===1?S.ac1:S.ac2))amp+=ch===1?S.offset:0;if(ch===1?S.inv1:S.inv2)amp=-amp;let y=pos-amp*ratio/vdiv*42.5;if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.font="12px sans-serif";ctx.fillText(ch===1?"1":"2",4,pos-4)});
ctx.fillStyle="#71909b";ctx.font="11px sans-serif";ctx.fillText("教学波形 · "+(S.power?"12 V":"电源 OFF"),535,328);if(!S.run){ctx.fillStyle="#ffd18a";ctx.fillText("STOP · 停止采集",270,24)}}
function refresh(){drawBoard();softMenu();$("runtext").textContent=S.run?"RUN":"STOP";$("timelabel").textContent=(S.time*1e6).toFixed(0)+" μs/div";$("trigtext").textContent=S.trig?(S.gen&&Math.abs(S.level)<Math.SQRT2*ui()?"触发 CH1 ↑ "+(S.level*1000).toFixed(0)+" mV":"等待触发"):"未稳定触发";$("ch1text").textContent="CH1 "+(S.v1*1000).toFixed(0)+" mV/div "+(S.ac1?"AC":"DC")+" "+S.probe1+"X";$("ch2text").textContent="CH2 "+S.v2+" V/div "+(S.ac2?"AC":"DC")+" "+S.probe2+"X";if(S.run)$("readings").textContent=S.measures.length?S.measures.map(m=>"CH"+m.source+" "+m.type+": "+reading(m.source,m.type)).join("   "):"按 Measure → Add Measurement";$("v1").value=S.v1;$("v2").value=S.v2;$("time").value=S.time;$("physicalprobe").value=S.physical;$("b-run").classList.toggle("on",S.run);$("b-goutput").classList.toggle("on",S.gen);$("b-poutput").classList.toggle("on",S.power);$("gfreq").textContent=(S.freq/1000).toFixed(3)+" kHz";$("gamp").textContent=S.amp.toFixed(2)+" mV RMS";$("goffset").textContent=S.offset.toFixed(3)+" V";$("gload").textContent=S.loadZ?"High Z":"50 Ω";$("gout").textContent=S.gen?"ON":"OFF";$("gentry").textContent=entry||({freq:(S.freq/1000).toFixed(3)+" kHz",amp:S.amp.toFixed(2)+" mV RMS",offset:S.offset.toFixed(3)+" V"})[param];$("gwarn").textContent=S.loadZ?"接近高阻输入时选 High Z；开启输出后仍以示波器测得的 Ui 为准。":"当前选择 50 Ω，但放大器输入不是 50 Ω：本演示中输入幅值约翻倍。改为 High Z 并核对 Ui。";$("pv").textContent=S.voltage.toFixed(3)+" V";$("ps").textContent=S.power?"ON":"OFF";$("pvoltage").value=S.voltage;drawMeter();drawScope()}
function drawMeter(){const r=$("redpoint").value,b=$("blackpoint").value;let val=0;if(meterMode==="DCV"){const v={B:S.power?S.ve+.68:0,E:S.power?S.ve:0,C:S.power?S.vc:0,GND:0,Ui:S.offset,Uo:0};val=v[r]-v[b]}if(meterMode==="ACV")val=r==="Ui"?ui():r==="Uo"?outputRms():0;
if(meterMode==="Ω"){const values={rc:2400,re:1000,rb1:S.cut?100000:20000,rb2:20000,rp:potResistance()},v=values[$("ohmpart").value];$("mread").textContent=S.power||S.gen?"先关双输出":(v/1000).toFixed(2)+" kΩ";$("mhint").textContent=S.power||S.gen?"测电阻前关闭直流电源和信号源。":"演示：取下选中的插件块，用红黑夹测两端。这里是模型阻值，课堂填写实测值。";}
else{$("mread").textContent=val.toFixed(3)+" V";$("mhint").textContent=meterMode+" · 红夹 "+r+" / 黑夹 "+b+"。"+(meterMode==="DCV"&&r==="C"&&b==="E"?"现在测 U_CE = V_C − V_E。":meterMode==="ACV"?"测交流有效值时选择 Ui 或 Uo。":"各点对地电压用黑夹 GND。")}}
function potResistance(){const ib=(12-S.vc)/2400/200,base=S.ve+.68,upper=base/20000+ib;return Math.max(0,(12-base)/upper-(S.cut?100000:20000))}

function operate(a){switch(a){case"ch1":selected=1;S.ch1=true;menu="channel";break;case"ch2":selected=2;S.ch2=true;menu="channel";break;case"measure":menu="measure";break;case"trigger":menu="trigger";break;case"vscale":{let k=selected===1?"v1":"v2",arr=selected===1?[.002,.005,.01,.02]:[.05,.1,.2,.5,1,2];S[k]=arr[(arr.indexOf(S[k])+1)%arr.length];break}case"tscale":{let arr=[.0001,.0002,.0005,.001];S.time=arr[(arr.indexOf(S.time)+1)%arr.length];break}case"position":{let k=selected===1?"pos1":"pos2";S[k]=(S[k]%7)+1;break}case"hposition":S.hpos=(S.hpos+.2)%1;break;case"level":S.level=S.level===0?.01:S.level===.01?-.01:0;S.trig=true;break;case"autoset":S.ch1=S.ch2=true;S.v1=.005;S.v2=1;S.time=.0002;S.trig=true;break;case"run":S.run=!S.run;break;case"sine":S.sine=true;break;case"freq":case"amp":case"offset":param=a;entry="";break;case"loadz":S.loadZ=!S.loadZ;break;case"goutput":S.gen=!S.gen;break;case"poutput":S.power=!S.power;break;case"dcv":meterMode="DCV";break;case"acv":meterMode="ACV";break;case"ohm":meterMode="Ω";break;case"savewave":{const a=document.createElement("a");a.download="实验五_教学模拟波形.png";a.href=$("wave").toDataURL("image/png");a.click();break}}refresh()}
function commit(unit){let n=Number(entry);if(!entry||!Number.isFinite(n))return;if(param==="freq"&&(unit==="Hz"||unit==="kHz"))S.freq=Math.max(1,n*(unit==="kHz"?1000:1));if(param==="amp"&&(unit==="mVrms"||unit==="mVpp"))S.amp=Math.max(.1,n/(unit==="mVpp"?2*Math.SQRT2:1));if(param==="offset"&&unit==="V")S.offset=n;entry="";refresh()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));$("saved").textContent="已保存课堂实测记录"}catch(e){$("saved").textContent="此浏览器不允许本地保存"}}
function esc(s){return String(s).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;")}
function inp(k,p){return '<input class="cell" data-k="'+k+'" placeholder="'+p+'" value="'+esc(data[k]||"")+'">'}
function renderData(){let h="",f="",x=inp;if(ti===0){document.getElementById("data-title").textContent="表 5-2｜静态工作点";h='<div class="tablewrap"><table><tr><th>参数</th><th>U_BE/V</th><th>U_CE/V</th><th>V_B/V</th><th>V_E/V</th><th>V_C/V</th></tr><tr><th>实测</th><td>'+x("ube","V")+'</td><td>'+x("uce","V")+'</td><td>'+x("vb","V")+'</td><td>'+x("ve","V")+'</td><td>'+x("vc","V")+'</td></tr><tr><th>电阻/kΩ</th><th>R_C</th><th>R_E</th><th>R_P</th><th>R_b1</th><th>R_b2</th></tr><tr><th>实测</th><td>'+x("rc","kΩ")+'</td><td>'+x("re","kΩ")+'</td><td>'+x("rp","kΩ")+'</td><td>'+x("rb1","kΩ")+'</td><td>'+x("rb2","kΩ")+'</td></tr><tr><th>计算</th><td>I_B/μA<br><b class="result" id="ib">—</b></td><td>I_C/mA<br><b class="result" id="ic">—</b></td><td>β<br><b class="result" id="beta">—</b></td><td colspan="2">自动估算</td></tr></table></div>';f="I_B(μA)=1000×[(12−V_B)/(R_P+R_b1)−V_B/R_b2]；I_C(mA)≈(12−V_C)/R_C(kΩ)；β=1000×I_C/I_B。";
}else if(ti===1){document.getElementById("data-title").textContent="表 5-3｜C_E 对增益的影响";h='<div class="tablewrap"><table><tr><th>条件</th><th>U_i/mV RMS</th><th>U_o/V RMS</th><th>A_u=|U_o|/|U_i|</th></tr><tr><th>C_E=47 μF</th><td>'+x("ce1ui","mV")+'</td><td>'+x("ce1uo","V")+'</td><td><b class="result" id="ce1">—</b></td></tr><tr><th>C_E 断开</th><td>'+x("ce0ui","mV")+'</td><td>'+x("ce0uo","V")+'</td><td><b class="result" id="ce0">—</b></td></tr></table></div>';f="固定 1 kHz、输入 10 mV RMS、R_L=1 MΩ 与静态偏置，只改变 C_E。";
}else if(ti===2){document.getElementById("data-title").textContent="表 5-4｜交流电压放大倍数";let rows=[["∞（开路）","open"],["10 kΩ","10k"],["1 kΩ","1k"]];h='<div class="tablewrap"><table><tr><th>负载</th><th>U_i/mV RMS</th><th>U_o/V RMS</th><th>A_u</th></tr>'+rows.map(r=>'<tr><th>R_L='+r[0]+'</th><td>'+x(r[1]+"ui","mV")+'</td><td>'+x(r[1]+"uo","V")+'</td><td><b class="result" data-g="'+r[1]+'">—</b></td></tr>').join("")+'</table></div>';f="每次只改变 R_L；单位换算已自动处理。";
}else{document.getElementById("data-title").textContent="表 5-5｜静态点对输出波形影响";let c=[["合适 Q 点","good"],["饱和失真","sat"],["截止失真","cut"]],m=["U_CE/V","U_BE/V","V_B/V","V_E/V","V_C/V","I_B/μA","I_C/mA","最大无失真 U_o/V RMS"];h='<div class="tablewrap"><table><tr><th>参数</th>'+c.map(a=>'<th>'+a[0]+'</th>').join("")+'</tr>'+m.map((a,i)=>'<tr><th>'+a+'</th>'+c.map(z=>'<td>'+x(z[1]+i,a)+'</td>').join("")+'</tr>').join("")+'<tr><th>波形备注</th>'+c.map(z=>'<td><textarea class="cell" data-k="'+z[1]+'note" placeholder="削顶方向/照片编号">'+esc(data[z[1]+"note"]||"")+'</textarea></td>').join("")+'</tr></table></div>';f="按数据记录页保存波形截图；此处可记截图编号或削顶方向。"}document.getElementById("table").innerHTML=h;document.getElementById("formula").textContent=f;document.querySelectorAll("[data-k]").forEach(e=>e.oninput=()=>{data[e.dataset.k]=e.value;save();calc()});calc()}
function num(k){let n=Number(String(data[k]||"").replace(",","."));return Number.isFinite(n)?n:null}function put(id,n,d){let e=document.getElementById(id);if(e)e.textContent=n===null||!Number.isFinite(n)?"—":n.toFixed(d)}function gain(a,b){let u=num(a),o=num(b);return u===null||o===null||u<=0?null:o/(u/1000)}
function calc(){let vb=num("vb"),vc=num("vc"),rp=num("rp"),r1=num("rb1"),r2=num("rb2"),rc=num("rc"),ib=null,ic=null,be=null;if(vb!==null&&rp!==null&&r1!==null&&r2!==null&&rp+r1>0&&r2>0)ib=1000*((12-vb)/(rp+r1)-vb/r2);if(vc!==null&&rc!==null&&rc>0)ic=(12-vc)/rc;if(ib!==null&&ic!==null&&ib>0)be=1000*ic/ib;put("ib",ib,1);put("ic",ic,3);put("beta",be,1);put("ce1",gain("ce1ui","ce1uo"),2);put("ce0",gain("ce0ui","ce0uo"),2);document.querySelectorAll("[data-g]").forEach(e=>{let k=e.dataset.g,n=gain(k+"ui",k+"uo");e.textContent=n===null?"—":n.toFixed(2)})}

